import React, { useState, useEffect } from 'react';
import { collection, query, orderBy, addDoc, doc, updateDoc, deleteDoc, onSnapshot } from 'firebase/firestore';
import { db } from '../../firebase/firebase';

const SalesGuidesManager = ({ readOnly = false }) => {
  const [guides, setGuides] = useState([]);
  const [editingGuide, setEditingGuide] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    videoUrl: ''
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(
      collection(db, 'salesGuides'),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const guidesData = [];
      snapshot.forEach((doc) => {
        guidesData.push({
          id: doc.id,
          ...doc.data()
        });
      });
      setGuides(guidesData);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const guideData = {
        ...formData,
        createdAt: new Date(),
        updatedAt: new Date()
      };

      if (editingGuide) {
        await updateDoc(doc(db, 'salesGuides', editingGuide.id), {
          ...formData,
          updatedAt: new Date()
        });
      } else {
        await addDoc(collection(db, 'salesGuides'), guideData);
      }

      setFormData({ title: '', description: '', videoUrl: '' });
      setEditingGuide(null);
    } catch (error) {
      console.error('Error saving guide:', error);
      alert('Failed to save guide. Please try again.');
    }
  };

  const handleEdit = (guide) => {
    setFormData({
      title: guide.title || '',
      description: guide.description || '',
      videoUrl: guide.videoUrl || ''
    });
    setEditingGuide(guide);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this guide?')) {
      try {
        await deleteDoc(doc(db, 'salesGuides', id));
      } catch (error) {
        console.error('Error deleting guide:', error);
        alert('Failed to delete guide. Please try again.');
      }
    }
  };

  const extractVideoId = (url) => {
    if (!url) return null;
    // Match YouTube URLs in various formats
    const regExp = /^.*(?:(?:youtu.be\/|v\/|vi?\/|u\/\w\/|embed\/|shorts\/)|(?:(?:watch)?\?v(?:i)?=|&v(?:i)?=))([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[1].length === 11) ? match[1] : null;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-gray-900">
          {readOnly ? 'Sales Guides' : 'Manage Sales Guides'}
        </h1>
        <p className="mt-1 text-sm text-gray-500">
          {readOnly ? 'Browse our collection of sales guides' : 'Add, edit, or remove sales guides'}
        </p>
      </div>

      {!readOnly && (
        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-lg font-semibold mb-4">
            {editingGuide ? 'Edit Guide' : 'Add New Guide'}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="title" className="block text-sm font-medium text-gray-700">
                Title
              </label>
              <input
                type="text"
                id="title"
                name="title"
                value={formData.title}
                onChange={handleInputChange}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </div>

            <div>
              <label htmlFor="videoUrl" className="block text-sm font-medium text-gray-700">
                YouTube Video URL
              </label>
              <input
                type="url"
                id="videoUrl"
                name="videoUrl"
                value={formData.videoUrl}
                onChange={handleInputChange}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required={!editingGuide}
              />
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-gray-700">
                Description
              </label>
              <textarea
                id="description"
                name="description"
                rows={3}
                value={formData.description}
                onChange={handleInputChange}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
              />
            </div>

            <div className="flex justify-end space-x-3">
              {editingGuide && (
                <button
                  type="button"
                  onClick={() => {
                    setFormData({ title: '', description: '', videoUrl: '' });
                    setEditingGuide(null);
                  }}
                  className="inline-flex items-center px-4 py-2 border border-gray-300 text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                >
                  Cancel
                </button>
              )}
              <button
                type="submit"
                className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                {editingGuide ? 'Update Guide' : 'Add Guide'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* List of Guides */}
      <div className="bg-white rounded-lg shadow-md overflow-hidden">
        {!readOnly && (
          <h2 className="text-xl font-semibold p-6 border-b">
            Existing Guides
          </h2>
        )}
        
        {loading ? (
          <div className="p-6 text-center">Loading guides...</div>
        ) : guides.length === 0 ? (
          <div className="p-6 text-center text-gray-500">
            No guides found. {!readOnly && 'Add your first guide using the form above.'}
          </div>
        ) : (
          <ul className="divide-y divide-gray-200">
            {guides.map((guide) => {
              const videoId = extractVideoId(guide.videoUrl);
              // Try to get max resolution thumbnail, fallback to high quality if not available
              const thumbnailUrl = `https://img.youtube.com/vi/${videoId}/maxresdefault.jpg`;
              const fallbackThumbnailUrl = `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`;
              
              return (
                <li key={guide.id} className="p-6 hover:bg-gray-50">
                  <div className="flex flex-col space-y-4">
                    {/* Title */}
                    <h3 className="text-xl font-semibold text-gray-900">
                      {guide.title || 'Untitled Guide'}
                    </h3>
                    
                    {/* YouTube-style Thumbnail */}
                    {videoId && (
                      <div className="w-full max-w-xl mx-auto">
                        <a 
                          href={guide.videoUrl} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="block relative group"
                        >
                          <div className="relative pt-[56.25%] bg-gray-100 rounded-lg overflow-hidden shadow-md">
                            <img 
                              src={thumbnailUrl} 
                              alt={guide.title || 'Video Thumbnail'}
                              className="absolute inset-0 w-full h-full object-contain bg-black"
                              onError={(e) => {
                                if (e.target.src !== fallbackThumbnailUrl) {
                                  e.target.src = fallbackThumbnailUrl;
                                } else {
                                  e.target.src = 'https://via.placeholder.com/1280x720?text=No+Thumbnail';
                                }
                              }}
                            />
                            <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-20 transition-all duration-200 flex items-center justify-center">
                              <div className="w-16 h-16 bg-red-600 bg-opacity-90 rounded-full flex items-center justify-center transform group-hover:scale-110 transition-transform">
                                <svg className="w-8 h-8 text-white" fill="currentColor" viewBox="0 0 20 20">
                                  <path d="M6.3 2.841A1.5 1.5 0 004 4.11v11.78a1.5 1.5 0 002.3 1.269l9.344-5.89a1.5 1.5 0 000-2.538L6.3 2.84z" />
                                </svg>
                              </div>
                            </div>
                          </div>
                        </a>
                      </div>
                    )}
                    
                    {/* Description */}
                    <p className="text-gray-700">
                      {guide.description || 'No description provided.'}
                    </p>
                    
                    {/* Admin Actions */}
                    {!readOnly && (
                      <div className="mt-3 flex space-x-3">
                        <button
                          onClick={() => handleEdit(guide)}
                          className="text-sm text-blue-600 hover:text-blue-800"
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => handleDelete(guide.id)}
                          className="text-sm text-red-600 hover:text-red-800"
                        >
                          Delete
                        </button>
                      </div>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
};

export default SalesGuidesManager;
