import React from 'react';
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/authContext';

const AdminLayout = () => {
  const { currentUser, doSignOut } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const isActive = (path) => {
    return location.pathname === path ? 'bg-gray-200 text-gray-900' : 'text-gray-700 hover:bg-gray-100';
  };

  const handleSignOut = async () => {
    try {
      await doSignOut();
      navigate('/login');
    } catch (error) {
      console.error('Failed to sign out:', error);
    }
  };

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar */}
      <div className="w-64 bg-white shadow-md">
        <div className="p-4 flex items-center space-x-3 border-b">
          <img 
            src="/auto2000-logo.png" 
            alt="Auto2000 Logo" 
            className="h-10 w-auto" 
          />
          <h1 className="text-xl font-bold">Admin Panel</h1>
        </div>
        
        <nav className="p-4 space-y-1">
          <Link 
            to="/admin-dashboard" 
            className={`block px-4 py-2 rounded-md text-sm font-medium ${isActive('/admin-dashboard')}`}
          >
            Dashboard
          </Link>
          <Link 
            to="/admin/sales-guides" 
            className={`block px-4 py-2 rounded-md text-sm font-medium ${isActive('/admin/sales-guides')}`}
          >
            Manage Sales Guides
          </Link>
          <Link 
            to="/admin/approve-signup" 
            className={`block px-4 py-2 rounded-md text-sm font-medium ${isActive('/admin/approve-signup')}`}
          >
            Approve Signups
          </Link>
          <button
            onClick={handleSignOut}
            className="w-full text-left px-4 py-2 rounded-md text-sm font-medium text-red-600 hover:bg-red-50"
          >
            Sign Out
          </button>
        </nav>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-auto">
        <div className="bg-white shadow-sm">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
            <h2 className="text-lg font-medium text-gray-900">
              {location.pathname === '/admin-dashboard' && 'Dashboard'}
              {location.pathname === '/admin/sales-guides' && 'Sales Guides'}
              {location.pathname === '/admin/approve-signup' && 'Approve Signups'}
            </h2>
            <div className="flex items-center space-x-4">
              <span className="text-sm text-gray-600">
                {currentUser?.email}
              </span>
            </div>
          </div>
        </div>
        
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default AdminLayout;
