import React, { useState, useEffect } from 'react';
import { collection, query, orderBy, onSnapshot, where } from 'firebase/firestore';
import { db } from '../../../firebase/firebase';
import { useAuth } from '../../../contexts/authContext';
import { useNavigate } from 'react-router-dom';
import { doc, deleteDoc } from 'firebase/firestore';
import { reassignUnassignedInquiries, resetAssignmentTracker } from '../../../utils/inquiryAssignment';

// Auto2000 color scheme
const COLORS = {
  primary: '#E31937', // Auto2000 Red
  secondary: '#222222', // Dark Gray
  background: '#F8F9FA', // Light Gray Background
  text: '#333333', // Dark Text
  textLight: '#6C757D', // Light Text
  white: '#FFFFFF',
  border: '#E9ECEF', // Light Border
  success: '#28A745', // Green
  warning: '#FFC107', // Yellow
  danger: '#DC3545' // Red
};

const AdminDashboard = () => {
    const [inquiries, setInquiries] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showOnlyMine, setShowOnlyMine] = useState(false);
    const [reassigning, setReassigning] = useState(false);

    const { currentUser, doSignOut } = useAuth();
    const navigate = useNavigate();

    // Fetch inquiries from Firestore
    useEffect(() => {
        let q;
        if (showOnlyMine && currentUser) {
            console.log('Filtering inquiries for user:', currentUser.uid);
            q = query(
                collection(db, 'inquiries'),
                where('assignedTo.id', '==', currentUser.uid),
                orderBy('date', 'desc')
            );
        } else {
            q = query(
                collection(db, 'inquiries'),
                orderBy('date', 'desc')
            );
        }

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const newInquiries = snapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setInquiries(newInquiries);
            setLoading(false);
        });
        return () => unsubscribe();
    }, [showOnlyMine, currentUser]);

    const handleReassignInquiries = async () => {
        if (window.confirm('Are you sure you want to reassign all unassigned inquiries?')) {
            try {
                setReassigning(true);
                const result = await reassignUnassignedInquiries();
                alert(`Successfully reassigned ${result.count} inquiries`);
            } catch (error) {
                console.error('Failed to reassign inquiries:', error);
                alert('Failed to reassign inquiries. Check console for details.');
            } finally {
                setReassigning(false);
            }
        }
    };

    const handleResetAssignment = async () => {
        if (window.confirm('Are you sure you want to reset the assignment tracker? This will start assigning from the first salesman again.')) {
            try {
                setReassigning(true);
                await resetAssignmentTracker();
                alert('Assignment tracker has been reset. New inquiries will be assigned starting from the first salesman.');
            } catch (error) {
                console.error('Failed to reset assignment tracker:', error);
                alert('Failed to reset assignment tracker. Check console for details.');
            } finally {
                setReassigning(false);
            }
        }
    };


    return (
        <div className="min-h-screen" style={{ backgroundColor: COLORS.background }}>
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
                <div className="flex justify-between items-center mb-6">
                    <h1 className="text-2xl font-bold" style={{ color: COLORS.primary }}>Sales Dashboard</h1>
                    <div className="flex items-center space-x-4">
                        <span className="text-sm" style={{ color: COLORS.text }}>
                            {currentUser?.email}
                        </span>
                        <button
                            onClick={async () => {
                                try {
                                    await doSignOut();
                                    navigate('/login');
                                } catch (error) {
                                    console.error('Logout failed:', error);
                                }
                            }}
                            className="px-4 py-2 rounded-md text-sm font-medium"
                            style={{ 
                                backgroundColor: COLORS.primary, 
                                color: 'white',
                                transition: 'background-color 0.2s'
                            }}
                            onMouseOver={(e) => e.target.style.backgroundColor = '#c1121f'}
                            onMouseOut={(e) => e.target.style.backgroundColor = COLORS.primary}
                        >
                            Logout
                        </button>
                    </div>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-6 mb-6" style={{ border: `1px solid ${COLORS.border}` }}>
                    <div className="flex flex-col md:flex-row md:items-center md:justify-between">
                        <h3 className="text-lg font-medium mb-4 md:mb-0" style={{ color: COLORS.text }}>
                            Customer Inquiries
                        </h3>
                    <div className="flex flex-wrap items-center gap-4">
                        <div className="flex items-center space-x-2">
                            <span className="text-sm font-medium" style={{ color: COLORS.text }}>
                                {showOnlyMine ? 'Showing only your inquiries' : 'Showing all inquiries'}
                            </span>
                            <button
                                type="button"
                                onClick={() => setShowOnlyMine(!showOnlyMine)}
                                className="px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200"
                                style={{
                                    backgroundColor: showOnlyMine ? COLORS.primary : COLORS.white,
                                    color: showOnlyMine ? 'white' : COLORS.text,
                                    border: `1px solid ${showOnlyMine ? COLORS.primary : COLORS.border}`,
                                    minWidth: '100px',
                                    textAlign: 'center'
                                }}
                                onMouseOver={(e) => {
                                    if (!showOnlyMine) {
                                        e.target.style.backgroundColor = COLORS.border;
                                    }
                                }}
                                onMouseOut={(e) => {
                                    if (!showOnlyMine) {
                                        e.target.style.backgroundColor = COLORS.white;
                                    }
                                }}
                            >
                                {showOnlyMine ? 'Show All' : 'Show Mine'}
                            </button>
                        </div>
                        
                        <div className="h-6 w-px bg-gray-300"></div>
                        
                        <div className="flex items-center space-x-3">
                            <button
                                type="button"
                                onClick={handleReassignInquiries}
                                disabled={reassigning}
                                className="px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200"
                                style={{
                                    backgroundColor: COLORS.warning,
                                    color: COLORS.text,
                                    opacity: reassigning ? 0.7 : 1,
                                    border: `1px solid ${COLORS.warning}`,
                                    minWidth: '150px',
                                    textAlign: 'center'
                                }}
                            >
                                {reassigning ? 'Reassigning...' : 'Reassign Unassigned'}
                            </button>

                            <button
                                type="button"
                                onClick={handleResetAssignment}
                                disabled={reassigning}
                                className="px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200"
                                style={{
                                    backgroundColor: COLORS.white,
                                    color: COLORS.primary,
                                    border: `1px solid ${COLORS.primary}`,
                                    opacity: reassigning ? 0.7 : 1,
                                    minWidth: '150px',
                                    textAlign: 'center'
                                }}
                                title="Reset assignment counter to start from first salesman"
                                onMouseOver={(e) => e.target.style.backgroundColor = '#f8d7da'}
                                onMouseOut={(e) => e.target.style.backgroundColor = COLORS.white}
                            >
                                {reassigning ? 'Resetting...' : 'Reset Assignment'}
                            </button>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-6" style={{ border: `1px solid ${COLORS.border}` }}>
                    <div className="overflow-x-auto">
                        <table className="min-w-full divide-y" style={{ borderColor: COLORS.border }}>
                            <thead>
                                <tr>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Name
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Phone
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Email
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Car Interest
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Message
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Assigned To
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Status
                                    </th>
                                    <th className="px-6 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: COLORS.textLight, backgroundColor: '#F8F9FA' }}>
                                        Date
                                    </th>
                                    </tr>
                                </thead>
                            <tbody className="divide-y" style={{ borderColor: COLORS.border }}>
                                {loading ? (
                                    <tr>
                                        <td colSpan="8" className="px-6 py-8 text-center" style={{ color: COLORS.text }}>
                                            <div className="flex justify-center">
                                                <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2" style={{ borderColor: COLORS.primary }}></div>
                                            </div>
                                            <p className="mt-2">Loading inquiries...</p>
                                        </td>
                                    </tr>
                                ) : inquiries.length === 0 ? (
                                    <tr>
                                        <td colSpan="8" className="px-6 py-12 text-center" style={{ color: COLORS.textLight }}>
                                            <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                            </svg>
                                            <h3 className="mt-2 text-sm font-medium" style={{ color: COLORS.text }}>No inquiries</h3>
                                            <p className="mt-1 text-sm" style={{ color: COLORS.textLight }}>Get started by creating a new inquiry.</p>
                                        </td>
                                    </tr>
                                ) : (
                                    inquiries.map((inquiry) => (
                                        <tr key={inquiry.id} className="hover:bg-gray-50" style={{ transition: 'background-color 0.2s' }}>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="text-sm font-medium" style={{ color: COLORS.text }}>{inquiry.name || 'N/A'}</div>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="text-sm" style={{ color: COLORS.text }}>{inquiry.phone || 'N/A'}</div>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="text-sm" style={{ color: COLORS.primary }}>{inquiry.email || 'N/A'}</div>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="text-sm" style={{ color: COLORS.text }}>{inquiry.carInterest || 'N/A'}</div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="text-sm max-w-xs truncate" style={{ color: COLORS.text }} title={inquiry.message}>
                                                    {inquiry.message || 'No message'}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <div className="text-sm font-medium" style={{ color: COLORS.text }}>
                                                    {inquiry.assignedTo?.name || 'Unassigned'}
                                                </div>
                                                {inquiry.assignedTo?.email && (
                                                    <div className="text-xs" style={{ color: COLORS.textLight }}>
                                                        {inquiry.assignedTo.email}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span 
                                                    className="px-2.5 py-0.5 inline-flex text-xs font-medium rounded-full"
                                                    style={{
                                                        backgroundColor: 
                                                            inquiry.status === 'assigned' 
                                                                ? '#d4edda' 
                                                                : inquiry.status === 'unassigned'
                                                                    ? '#fff3cd'
                                                                    : '#d1ecf1',
                                                        color: 
                                                            inquiry.status === 'assigned'
                                                                ? '#155724'
                                                                : inquiry.status === 'unassigned'
                                                                    ? '#856404'
                                                                    : '#0c5460'
                                                    }}
                                                >
                                                    {inquiry.status || 'new'}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm" style={{ color: COLORS.textLight }}>
                                                {inquiry.date?.toDate ? inquiry.date.toDate().toLocaleString() : 'N/A'}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                                <button
                                                    onClick={async () => {
                                                        if (window.confirm('Are you sure you want to delete this inquiry?')) {
                                                            try {
                                                                await deleteDoc(doc(db, 'inquiries', inquiry.id));
                                                            } catch (error) {
                                                                console.error('Failed to delete inquiry:', error);
                                                                alert('Failed to delete inquiry. Please try again.');
                                                            }
                                                        }
                                                    }}
                                                    className="text-red-600 hover:text-red-900"
                                                    style={{ transition: 'color 0.2s' }}
                                                >
                                                    Delete
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
};
export default AdminDashboard;
