import React, { useState, useEffect } from 'react'
import { Navigate, Link, useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../../../contexts/authContext'
import { sendSignupRequest } from './signupRequest'

import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '../../../firebase/firebase';

const Login = () => {
    // All hooks at the top!
    const {
        currentUser,
        userLoggedIn,
        loading: authLoading,
        doSignInWithEmailAndPassword,
        doSignInWithGoogle
    } = useAuth();
    
    const location = useLocation();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isSigningIn, setIsSigningIn] = useState(false);
    const [errorMessage, setErrorMessage] = useState('');
    const [showSignup, setShowSignup] = useState(false);
    const [signupEmail, setSignupEmail] = useState('');
    const [signupMessage, setSignupMessage] = useState('');
    const [signupSuccess, setSignupSuccess] = useState(false);
    const [signupError, setSignupError] = useState('');
    const [notification, setNotification] = useState('');
    const [loginAsAdmin, setLoginAsAdmin] = useState(false);
    const [signupLoading, setSignupLoading] = useState(false);
    
    // Debug logging
    console.log('[Login] Auth loading:', authLoading);
    console.log('[Login] Current user:', currentUser);
    console.log('[Login] User logged in:', userLoggedIn);

    // Real-time approval check for signup
    React.useEffect(() => {
        if (currentUser && currentUser.email) {
            // Check if user is already registered
            import('firebase/auth').then(({ getAuth, fetchSignInMethodsForEmail }) => {
                const auth = getAuth();
                fetchSignInMethodsForEmail(auth, currentUser.email).then(methods => {
                    if (methods && methods.length > 0) {
                        // User is already registered, do nothing
                        return;
                    }
                    // Not yet registered, listen for approval
                    const q = query(
                        collection(db, 'signup_requests'),
                        where('email', '==', currentUser.email)
                    );
                    const unsub = onSnapshot(q, (snapshot) => {
                        let found = false;
                        snapshot.forEach(doc => {
                            if (doc.data().approved) {
                                found = true;
                            }
                        });
                        if (found) {
                            setNotification('Akun kamu sudah di-approve! Silakan login kembali.');
                        }
                    });
                    return () => unsub();
                });
            });
        }
    }, [currentUser, navigate]);

    // Show loading state while auth is initializing
    if (authLoading) {
        return (
            <div className="w-full h-screen flex flex-col justify-center items-center dark:bg-gray-900 space-y-4">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
                <div className="text-gray-600 dark:text-gray-200">Memeriksa autentikasi...</div>
            </div>
        );
    }

    const onSubmit = async (e) => {
        e.preventDefault();
        if (isSigningIn) return;
        
        setIsSigningIn(true);
        setErrorMessage('');
        console.log('[Login] Attempting login with:', { email, loginAsAdmin });
        
        try {
            // First, try to sign in with email/password
            console.log('[Login] Calling doSignInWithEmailAndPassword');
            await doSignInWithEmailAndPassword(email, password);
            
            console.log('[Login] Login successful, checking admin status...');
            
            if (loginAsAdmin) {
                // Check admin list in Firestore
                const { doc, getDoc } = await import('firebase/firestore');
                console.log('[Login] Checking admin access for:', email);
                const adminDoc = await getDoc(doc(db, 'site_content', 'admins'));
                
                if (!adminDoc.exists()) {
                    console.error('[Login] No admin document found');
                    setErrorMessage('Data admin tidak ditemukan di server. Hubungi pengelola.');
                    return;
                }
                
                const adminData = adminDoc.data();
                console.log('[Login] Admin data:', adminData);
                
                if (Array.isArray(adminData.email) && adminData.email.includes(email)) {
                    console.log('[Login] Admin access granted, redirecting to admin dashboard');
                    navigate('/admin/products', { replace: true });
                } else {
                    console.warn('[Login] Admin access denied for email:', email);
                    setErrorMessage('Email ini tidak diotorisasi sebagai admin.');
                }
            } else {
                console.log('[Login] Regular user, redirecting to dashboard');
                navigate('/encrypted-dashboard', { replace: true });
            }
        } catch (error) {
            console.error('[Login] Error during sign in:', error);
            setErrorMessage(error.message || 'Email atau password kamu salah. Coba lagi ya, atau klik "Lupa Password" untuk reset.');
        } finally {
            setIsSigningIn(false);
        }
    };

    const onGoogleSignIn = async (e) => {
        e.preventDefault();
        if (!isSigningIn) {
            setIsSigningIn(true);
            setErrorMessage("");
            console.log("[DEBUG] Attempting Google Sign-In...");
            try {
                await doSignInWithGoogle();
                console.log("[DEBUG] Google Sign-In successful");
                // Redirect based on admin status if needed
                navigate("/encrypted-dashboard", { replace: true });
            } catch (error) {
                console.error("[DEBUG] Google Sign-In error:", error);
                setErrorMessage(error.message || 'Gagal login dengan Google. Silakan coba lagi.');
            } finally {
                setIsSigningIn(false);
            }
        }
    };

    const handleSignupRequest = async (e) => {
        e.preventDefault();
        setSignupLoading(true);
        setSignupError('');
        try {
            await sendSignupRequest(signupEmail, signupMessage);
            setSignupSuccess(false); // Always waiting for approval after request
            setNotification('Waiting for admin approval.');
            setSignupEmail('');
            setSignupMessage('');
            // Log out the currentUser after request
            setTimeout(async () => {
                if (typeof window !== 'undefined' && window.localStorage) {
                    window.localStorage.clear(); // Clear local storage (optional, extra safety)
                }
                if (window.firebase && window.firebase.auth) {
                    await window.firebase.auth().signOut();
                } else {
                    try {
                        const { getAuth, signOut } = await import('firebase/auth');
                        const auth = getAuth();
                        await signOut(auth);
                    } catch {}
                }
                navigate('/login');
            }, 1500); // 1.5 seconds for currentUser to see notification
        } catch (err) {
            setSignupError('Gagal mengirim permintaan signup. Coba lagi nanti.');
        } finally {
            setSignupLoading(false);
        }
    };

    return (
        <div>
            <main className="w-full h-screen flex self-center place-content-center place-items-center bg-white dark:bg-gray-900">
                <div className="w-96 text-gray-600 dark:text-gray-100 space-y-5 p-4 shadow-xl border border-gray-200 dark:border-gray-700 rounded-xl bg-white dark:bg-gray-900">
                    <div className="text-center">
                        <div className="mt-2">
                            <h3 className="text-gray-800 dark:text-gray-100 text-xl font-semibold sm:text-2xl">Welcome Astra Sales</h3>
                        </div>
                    </div>
                    <form onSubmit={onSubmit} className="space-y-5">
    <div className="flex items-center mb-2">
        <input
            id="loginAsAdmin"
            type="checkbox"
            checked={loginAsAdmin}
            onChange={e => setLoginAsAdmin(e.target.checked)}
            className="mr-2"
        />
        <label htmlFor="loginAsAdmin" className="text-sm text-gray-700 dark:text-gray-200">Login as Admin</label>
    </div>
                        {errorMessage && (
                            <div className="text-red-500 text-sm mb-2">{errorMessage}</div>
                        )}
                        <div>
                            <label className="text-sm text-gray-600 dark:text-gray-200 font-bold">Email</label>
                            <input
                                type="email"
                                autoComplete="email"
                                required
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full mt-2 px-3 py-2 text-gray-500 dark:text-gray-100 bg-transparent dark:bg-gray-800 outline-none border border-gray-300 dark:border-gray-700 focus:border-indigo-600 shadow-sm rounded-lg transition duration-300"
                            />
                        </div>
                        <div>
                            <label className="text-sm text-gray-600 dark:text-gray-200 font-bold">Password</label>
                            <input
                                type="password"
                                autoComplete="current-password"
                                required
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="w-full mt-2 px-3 py-2 text-gray-500 dark:text-gray-100 bg-transparent dark:bg-gray-800 outline-none border border-gray-300 dark:border-gray-700 focus:border-indigo-600 shadow-sm rounded-lg transition duration-300"
                            />
                        </div>

                        {errorMessage && (
                            <span className='text-red-600 font-bold'>{errorMessage}</span>
                        )}

                        <button
                            type="submit"
                            disabled={isSigningIn}
                            className={`w-full px-4 py-2 text-white font-medium rounded-lg ${isSigningIn ? 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed' : 'bg-indigo-600 dark:bg-indigo-700 hover:bg-indigo-700 dark:hover:bg-indigo-800 hover:shadow-xl transition duration-300'}`}
                        >
                            {isSigningIn ? 'Signing In...' : 'Sign In'}
                        </button>
                    </form>
                    <p className="text-center text-sm">
                        <Link to={'/forgot-password'} className="hover:underline font-bold">Forgot password?</Link>
                    </p>
                    <div className='flex flex-row text-center w-full'>
                        <div className='border-b-2 mb-2.5 mr-2 w-full border-gray-200 dark:border-gray-700'></div><div className='text-sm font-bold w-fit'>OR</div><div className='border-b-2 mb-2.5 ml-2 w-full border-gray-200 dark:border-gray-700'></div>
                    </div>
                    <button
                        disabled={isSigningIn}
                        onClick={(e) => { onGoogleSignIn(e) }}
                        className={`w-full flex items-center justify-center gap-x-3 py-2.5 border dark:border-gray-700 rounded-lg text-sm font-medium  ${isSigningIn ? 'cursor-not-allowed' : 'hover:bg-gray-100 dark:hover:bg-gray-700 transition duration-300 active:bg-gray-100 dark:active:bg-gray-700'}`}>
                        <svg className="w-5 h-5" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <g clipPath="url(#clip0_17_40)">
                                <path d="M47.532 24.5528C47.532 22.9214 47.3997 21.2811 47.1175 19.6761H24.48V28.9181H37.4434C36.9055 31.8988 35.177 34.5356 32.6461 36.2111V42.2078H40.3801C44.9217 38.0278 47.532 31.8547 47.532 24.5528Z" fill="#4285F4" />
                                <path d="M24.48 48.0016C30.9529 48.0016 36.4116 45.8764 40.3888 42.2078L32.6549 36.2111C30.5031 37.675 27.7252 38.5039 24.4888 38.5039C18.2275 38.5039 12.9187 34.2798 11.0139 28.6006H3.03296V34.7825C7.10718 42.8868 15.4056 48.0016 24.48 48.0016Z" fill="#34A853" />
                                <path d="M11.0051 28.6006C9.99973 25.6199 9.99973 22.3922 11.0051 19.4115V13.2296H3.03298C-0.371021 20.0112 -0.371021 28.0009 3.03298 34.7825L11.0051 28.6006Z" fill="#FBBC04" />
                                <path d="M24.48 9.49932C27.9016 9.44641 31.2086 10.7339 33.6866 13.0973L40.5387 6.24523C36.2 2.17101 30.4414 -0.068932 24.48 0.00161733C15.4055 0.00161733 7.10718 5.11644 3.03296 13.2296L11.005 19.4115C12.901 13.7235 18.2187 9.49932 24.48 9.49932Z" fill="#EA4335" />
                            </g>
                            <defs>
                                <clipPath id="clip0_17_40">
                                    <rect width="48" height="48" fill="white" />
                                </clipPath>
                            </defs>
                        </svg>
                        {isSigningIn ? 'Signing In...' : 'Continue with Google'}
                    </button>
                </div>
            </main>
            {/* Signup Modal */}
            {showSignup && (
    <div className="fixed inset-0 bg-black bg-opacity-60 flex justify-center items-center z-50">
        <div className="bg-white dark:bg-gray-900 p-6 rounded-lg shadow-lg w-full max-w-md">
            <h2 className="text-xl font-bold mb-4 dark:text-gray-100">{signupSuccess ? 'Sign Up' : 'Request Sign Up'}</h2>
            {signupSuccess ? (
  <div className="flex flex-col items-center gap-3 mb-4">
    <div className="text-green-600 dark:text-green-400">Request accepted. You may now sign up.</div>
    <button
      className="w-full py-2 px-4 bg-indigo-600 dark:bg-indigo-700 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2"
      onClick={() => { navigate('/signup'); }}
    >
      Go to Sign Up
    </button>
  </div>
) : (
  <>
    <div className="text-yellow-600 dark:text-yellow-400 mb-4 text-center">Waiting for admin approval.</div>
    <form onSubmit={handleSignupRequest} className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Email</label>
        <input type="email" value={signupEmail} onChange={e => setSignupEmail(e.target.value)} required className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500" />
      </div>
      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Pesan</label>
        <textarea value={signupMessage} onChange={e => setSignupMessage(e.target.value)} required className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500" />
      </div>
      {signupError && <div className="text-red-600 dark:text-red-400">{signupError}</div>}
      <button type="submit" disabled={signupLoading} className="w-full py-2 px-4 bg-indigo-600 dark:bg-indigo-700 text-white rounded-md hover:bg-indigo-700 dark:hover:bg-indigo-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2">{signupLoading ? 'Mengirim...' : 'Kirim Permintaan'}</button>
    </form>
  <button
    className="mt-4 w-full py-2 px-4 bg-gray-300 dark:bg-gray-600 rounded-md hover:bg-gray-400 dark:hover:bg-gray-500"
    onClick={() => {
      setShowSignup(false);
      setSignupSuccess(false);
      setSignupError('');
      setNotification('');
    }}
  >
    Tutup
  </button>
</>
  )}
        </div>
    </div>
)}
{notification && (
    <div className="fixed top-6 right-6 bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded shadow z-50">
        {notification}
        <button className="ml-4 text-green-900 font-bold" onClick={() => setNotification('')}>x</button>
    </div>
)}
<div className="fixed bottom-6 right-6">
    <button className="bg-green-600 text-white px-4 py-2 rounded-lg shadow hover:bg-green-700" onClick={() => setShowSignup(true)}>
        {signupSuccess ? 'Sign Up' : 'Request Sign Up'}
    </button>
</div>
        </div>
    )
}

export default Login