import React, { useState } from 'react';
import { useSearchParams } from 'react-router-dom';

import { db } from '../../firebase/firebase';
import { doc, updateDoc } from 'firebase/firestore';

function ApproveSignup() {
  const [searchParams] = useSearchParams();
  const email = searchParams.get('email');
  const [approved, setApproved] = useState(false);
  const [error, setError] = useState('');

  const handleApprove = async () => {
    try {
      // Update the signup_requests document for this email to set status: 'approved'
      const requestRef = doc(db, 'signup_requests', email);
      await updateDoc(requestRef, { status: 'approved' });
      setApproved(true);
      setError('');
    } catch (err) {
      setError('Failed to approve signup.');
    }
  };


  if (!email) {
    return <div>No email provided in the approval link.</div>;
  }

  return (
    <div style={{ maxWidth: 400, margin: '40px auto', padding: 24, border: '1px solid #eee', borderRadius: 12, background: '#fff', textAlign: 'center' }}>
      <h2>Approve Signup Request</h2>
      <p><strong>Email:</strong> {email}</p>
      {approved ? (
        <div style={{ color: 'green', marginTop: 16 }}>Signup approved! You may now create an account for this user.</div>
      ) : (
        <>
          <button onClick={handleApprove} style={{ background: '#22c55e', color: '#fff', border: 'none', padding: '10px 24px', borderRadius: 6, cursor: 'pointer', fontWeight: 'bold' }}>
            Grant Access
          </button>
          {error && <div style={{ color: 'red', marginTop: 16 }}>{error}</div>}
        </>
      )}
    </div>
  );
}

export default ApproveSignup;
