import React, { createContext, useState, useEffect } from 'react';
import { 
    onAuthStateChanged,
    signInWithEmailAndPassword,
    signInWithPopup,
    GoogleAuthProvider,
    signOut,
    createUserWithEmailAndPassword,
    sendEmailVerification,
    sendPasswordResetEmail
} from 'firebase/auth';
import { auth } from '../firebase/firebase';

// Create the context with default values
const AuthContext = createContext({
    user: null,
    userLoggedIn: false,
    isEmailUser: false,
    isGoogleUser: false,
    currentUser: null,
    loading: true,
    doSignInWithEmailAndPassword: () => {},
    doSignInWithGoogle: () => {},
    doSignOut: () => {},
    doCreateUserWithEmailAndPassword: () => {},
    doSendEmailVerification: () => {},
    doSendPasswordResetEmail: () => {}
});

// Custom hook to use the auth context
export const useAuth = () => {
    const context = React.useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

// Auth Provider component
export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [userLoggedIn, setUserLoggedIn] = useState(false);
    const [isEmailUser, setIsEmailUser] = useState(false);
    const [isGoogleUser, setIsGoogleUser] = useState(false);
    const [currentUser, setCurrentUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Listen for auth state changes
        const unsubscribe = onAuthStateChanged(auth, (user) => {
            console.log('[AuthContext] Auth state changed:', user);
            setUser(user);
            setCurrentUser(user);
            setUserLoggedIn(!!user);
            if (user) {
                const isEmail = user.providerData.some(
                    provider => provider.providerId === 'password'
                );
                const isGoogle = user.providerData.some(
                    provider => provider.providerId === 'google.com'
                );
                setIsEmailUser(isEmail);
                setIsGoogleUser(isGoogle);
            } else {
                setIsEmailUser(false);
                setIsGoogleUser(false);
            }
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const doSignInWithEmailAndPassword = async (email, password) => {
        try {
            await signInWithEmailAndPassword(auth, email, password);
        } catch (error) {
            console.error('Login error:', error.code, error.message);
            if (error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
                throw new Error('Email atau password salah. Silakan coba lagi.');
            } else if (error.code === 'auth/too-many-requests') {
                throw new Error('Terlalu banyak percobaan login. Silakan coba lagi nanti atau reset password Anda.');
            } else {
                throw new Error('Terjadi kesalahan saat login. Silakan coba lagi.');
            }
        }
    };

    const doSignInWithGoogle = async () => {
        try {
            const provider = new GoogleAuthProvider();
            provider.setCustomParameters({
                prompt: 'select_account' // Forces account selection even when one account is available
            });
            await signInWithPopup(auth, provider);
        } catch (error) {
            console.error('Google Sign-In error:', error.code, error.message);
            if (error.code === 'auth/account-exists-with-different-credential') {
                throw new Error('Email ini sudah terdaftar dengan metode login yang berbeda. Silakan gunakan metode login yang sesuai.');
            } else if (error.code === 'auth/popup-closed-by-user') {
                throw new Error('Popup login ditutup. Silakan coba lagi.');
            } else {
                throw new Error('Gagal login dengan Google. Silakan coba lagi.');
            }
        }
    };

    const doSignOut = async () => {
        try {
            await signOut(auth);
        } catch (error) {
            throw new Error('Failed to sign out');
        }
    };

    const doCreateUserWithEmailAndPassword = async (email, password) => {
        try {
            await createUserWithEmailAndPassword(auth, email, password);
        } catch (error) {
            throw new Error(error.message);
        }
    };

    const doSendEmailVerification = async () => {
        try {
            await sendEmailVerification(auth.currentUser);
        } catch (error) {
            throw new Error('Failed to send verification email');
        }
    };

    const doSendPasswordResetEmail = async (email) => {
        console.log('[AUTH] Attempting to send password reset email to:', email);
        try {
            await sendPasswordResetEmail(auth, email);
            console.log('[AUTH] Password reset email sent successfully to:', email);
            return true;
        } catch (error) {
            console.error('[AUTH] Password reset error:', {
                code: error.code,
                message: error.message,
                email: email,
                timestamp: new Date().toISOString()
            });
            
            // Common Firebase Auth error codes for password reset
            switch (error.code) {
                case 'auth/user-not-found':
                    throw new Error('Email tidak terdaftar. Pastikan email yang Anda masukkan sudah benar.');
                case 'auth/invalid-email':
                    throw new Error('Format email tidak valid. Mohon masukkan alamat email yang benar.');
                case 'auth/too-many-requests':
                    throw new Error('Terlalu banyak permintaan. Silakan tunggu beberapa saat sebelum mencoba lagi.');
                case 'auth/operation-not-allowed':
                    console.error('[AUTH] Password reset is not enabled in Firebase Console');
                    throw new Error('Reset password tidak diaktifkan. Silakan hubungi administrator.');
                default:
                    console.error('[AUTH] Unexpected error during password reset:', error);
                    throw new Error('Terjadi kesalahan saat mengirim email reset password. Silakan coba lagi nanti.');
            }
        }
    };

    // Create a stable reference to all context values
    const value = React.useMemo(() => ({
        // State values
        user,
        userLoggedIn,
        isEmailUser,
        isGoogleUser,
        currentUser,
        loading,
        
        // State setters
        setCurrentUser,
        
        // Auth methods
        doSignInWithEmailAndPassword: async (email, password) => {
            try {
                await signInWithEmailAndPassword(auth, email, password);
            } catch (error) {
                console.error('Login error:', error.code, error.message);
                if (error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
                    throw new Error('Email atau password salah. Silakan coba lagi.');
                } else if (error.code === 'auth/too-many-requests') {
                    throw new Error('Terlalu banyak percobaan login. Silakan coba lagi nanti atau reset password Anda.');
                } else {
                    throw new Error('Terjadi kesalahan saat login. Silakan coba lagi.');
                }
            }
        },
        
        doSignInWithGoogle: async () => {
            try {
                const provider = new GoogleAuthProvider();
                provider.setCustomParameters({
                    prompt: 'select_account' // Forces account selection even when one account is available
                });
                await signInWithPopup(auth, provider);
            } catch (error) {
                console.error('Google Sign-In error:', error.code, error.message);
                if (error.code === 'auth/account-exists-with-different-credential') {
                    throw new Error('Email ini sudah terdaftar dengan metode login yang berbeda. Silakan gunakan metode login yang sesuai.');
                } else if (error.code === 'auth/popup-closed-by-user') {
                    throw new Error('Popup login ditutup. Silakan coba lagi.');
                } else {
                    throw new Error('Gagal login dengan Google. Silakan coba lagi.');
                }
            }
        },
        
        doSignOut: async () => {
            try {
                await signOut(auth);
            } catch (error) {
                throw new Error('Gagal keluar. Silakan coba lagi.');
            }
        },
        
        doCreateUserWithEmailAndPassword: async (email, password) => {
            try {
                await createUserWithEmailAndPassword(auth, email, password);
            } catch (error) {
                throw new Error(error.message);
            }
        },
        
        doSendEmailVerification: async () => {
            try {
                if (auth.currentUser) {
                    await sendEmailVerification(auth.currentUser);
                } else {
                    throw new Error('Tidak ada pengguna yang masuk');
                }
            } catch (error) {
                throw new Error('Gagal mengirim email verifikasi: ' + error.message);
            }
        },
        
        doSendPasswordResetEmail: async (email) => {
            console.log('[AUTH] Attempting to send password reset email to:', email);
            try {
                await sendPasswordResetEmail(auth, email);
                console.log('[AUTH] Password reset email sent successfully to:', email);
                return true;
            } catch (error) {
                console.error('[AUTH] Password reset error:', {
                    code: error.code,
                    message: error.message,
                    email: email,
                    timestamp: new Date().toISOString()
                });
                
                // Common Firebase Auth error codes for password reset
                switch (error.code) {
                    case 'auth/user-not-found':
                        throw new Error('Email tidak terdaftar. Pastikan email yang Anda masukkan sudah benar.');
                    case 'auth/invalid-email':
                        throw new Error('Format email tidak valid. Mohon masukkan alamat email yang benar.');
                    case 'auth/too-many-requests':
                        throw new Error('Terlalu banyak permintaan. Silakan tunggu beberapa saat sebelum mencoba lagi.');
                    case 'auth/operation-not-allowed':
                        console.error('[AUTH] Password reset is not enabled in Firebase Console');
                        throw new Error('Reset password tidak diaktifkan. Silakan hubungi administrator.');
                    default:
                        console.error('[AUTH] Unexpected error during password reset:', error);
                        throw new Error('Terjadi kesalahan saat mengirim email reset password. Silakan coba lagi nanti.');
                }
            }
        }
    }), [user, userLoggedIn, isEmailUser, isGoogleUser, currentUser, loading]);

    console.log('[AuthContext] Render value:', value);
    
    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
};

// Export the AuthContext for direct usage if needed
export { AuthContext };

export default AuthProvider;
