import React, { useState } from 'react';
import { collection, addDoc } from 'firebase/firestore';
import { db } from '../../../firebase/firebase';
import { assignInquiry } from '../../../utils/inquiryAssignment';

const CustomerInquiry = ({ carInterestPrefill = '' }) => {
    const [name, setName] = useState('');
    const [phone, setPhone] = useState('');
    const [email, setEmail] = useState('');
    const [carInterest, setCarInterest] = useState(carInterestPrefill);
    const [message, setMessage] = useState('');
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [submitButtonText, setSubmitButtonText] = useState('Kirim Penawaran');
    const [error, setError] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setSubmitButtonText('Mengirim...');
        setError('');
        
        console.log('Starting form submission...');
        
        try {
            // Basic form validation
            if (!name || !phone || !email || !carInterest) {
                throw new Error('Harap isi semua kolom yang wajib diisi');
            }

            // Create inquiry data
            const inquiryData = {
                name: name.trim(),
                phone: phone.trim(),
                email: email.trim().toLowerCase(),
                carInterest: carInterest.trim(),
                message: message ? message.trim() : '',
                status: 'new',
                date: new Date(),
                updatedAt: new Date(),
                source: 'website'
            };

            console.log('Submitting inquiry:', inquiryData);
            
            // Assign the inquiry to a salesman
            console.log('Assigning inquiry to salesman...');
            const inquiryWithAssignment = await assignInquiry(inquiryData);
            console.log('Inquiry assigned:', inquiryWithAssignment);
            
            // Add to Firestore
            console.log('Saving to Firestore...');
            const inquiriesRef = collection(db, 'inquiries');
            const docRef = await addDoc(inquiriesRef, inquiryWithAssignment);
            console.log('Inquiry saved with ID:', docRef.id);

            // Clear form
            setName('');
            setPhone('');
            setEmail('');
            setCarInterest('');
            setMessage('');
            
            setSuccess(true);
            setSubmitButtonText('Berhasil Dikirim');
            console.log('Inquiry submission successful');
            
            setTimeout(() => {
                setSubmitButtonText('Kirim Penawaran Lainnya');
            }, 5000);
            
        } catch (err) {
            console.error('Error in handleSubmit:', {
                error: err,
                message: err.message,
                stack: err.stack
            });
            
            const errorMessage = err.message || 'Gagal mengirim inquiry. Silakan coba lagi.';
            setError(errorMessage);
            setSubmitButtonText('Gagal Mengirim');
            
            setTimeout(() => {
                setSubmitButtonText('Coba Lagi');
            }, 3000);
            
        } finally {
            setLoading(false);
        }
    };


    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-100 dark:bg-gray-900">
            <div className="w-full max-w-md p-8 space-y-6 bg-white dark:bg-gray-900 rounded-lg shadow-md">
                <h2 className="text-2xl font-bold text-center text-gray-800 dark:text-gray-100">Formulir Penawaran Mobil</h2>
                
                {error && (
                    <div className="p-2 text-center bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300 rounded-lg mb-2">{error}</div>
                )}
                {success ? (
                    <div className="p-4 text-center bg-green-100 dark:bg-green-900 text-green-700 dark:text-green-300 rounded-lg">
                        Terima kasih atas penawaran Anda! Tim penjualan kami akan menghubungi Anda segera.
                    </div>
                ) : (
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Nama Lengkap</label>
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                required
                                className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Nomor Telepon</label>
                            <input
                                type="tel"
                                value={phone}
                                onChange={(e) => setPhone(e.target.value)}
                                required
                                className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Alamat Email</label>
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                                className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Mobil yang Diminati</label>
                            <input
                                type="text"
                                value={carInterest}
                                onChange={(e) => setCarInterest(e.target.value)}
                                required
                                readOnly={!!carInterestPrefill}
                                className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 dark:text-gray-200">Message</label>
                            <textarea
                                value={message}
                                onChange={(e) => setMessage(e.target.value)}
                                required
                                className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                                rows="4"
                            ></textarea>
                        </div>

                        <button
                            type="submit"
                            disabled={loading}
                            className={`w-full px-4 py-2 text-white font-medium rounded-lg ${loading ? 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed' : 'bg-indigo-600 dark:bg-indigo-700 hover:bg-indigo-700 dark:hover:bg-indigo-800 hover:shadow-xl transition duration-300'}`}
                        >
                            {submitButtonText}
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
};

export default CustomerInquiry;
