import React, { useState } from 'react'
import { Navigate, Link } from 'react-router-dom'
import { useAuth } from '../../../contexts/authContext'

const ForgotPassword = () => {
    const { userLoggedIn, doSendPasswordResetEmail } = useAuth()
    const [email, setEmail] = useState('')
    const [isSending, setIsSending] = useState(false)
    const [message, setMessage] = useState('')

    const onSubmit = async (e) => {
        e.preventDefault()
        if (!isSending) {
            setIsSending(true)
            setMessage('')
            console.log('[DEBUG] Attempting to send password reset email to:', email)
            
            try {
                const success = await doSendPasswordResetEmail(email)
                if (success) {
                    console.log('[DEBUG] Password reset email sent successfully')
                    setMessage('Email reset password telah dikirim! Silakan periksa inbox atau folder spam email Anda.')
                    setEmail('')
                }
            } catch (error) {
                console.error('[DEBUG] Password reset error:', error)
                setMessage(error.message || 'Gagal mengirim email reset. Silakan coba lagi nanti.')
            } finally {
                setIsSending(false)
            }
        }
    }

    return (
        <div>
            {userLoggedIn && (<Navigate to={'/home'} replace={true} />)}

            <main className="w-full h-screen flex self-center place-content-center place-items-center dark:bg-gray-900">
                <div className="w-96 text-gray-600 dark:text-gray-100 space-y-5 p-4 shadow-xl border dark:border-gray-700 rounded-xl bg-white dark:bg-gray-900">
                    <div className="text-center mb-6">
                        <div className="mt-2">
                            <h3 className="text-gray-800 dark:text-gray-100 text-xl font-semibold sm:text-2xl">Forgot Password</h3>
                        </div>
                    </div>
                    
                    <form onSubmit={onSubmit} className="space-y-5">
                        {message && (
                            <div className={`text-sm mb-2 ${message.includes('sent') ? 'text-green-500 dark:text-green-400' : 'text-red-500 dark:text-red-400'}`}>
                                {message}
                            </div>
                        )}
                        <div>
                            <label className="text-sm text-gray-600 dark:text-gray-200 font-bold">
                                Email
                            </label>
                            <input
                                type="email"
                                autoComplete='email'
                                required
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="w-full mt-2 px-3 py-2 text-gray-500 dark:text-gray-100 bg-transparent outline-none border dark:border-gray-700 focus:border-indigo-600 shadow-sm rounded-lg transition duration-300"
                            />
                        </div>

                        <button
                            type="submit"
                            disabled={isSending}
                            className={`w-full px-4 py-2 text-white font-medium rounded-lg ${isSending ? 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed' : 'bg-indigo-600 dark:bg-indigo-700 hover:bg-indigo-700 dark:hover:bg-indigo-800 hover:shadow-xl transition duration-300'}`}
                        >
                            {isSending ? 'Sending...' : 'Send Reset Link'}
                        </button>
                    </form>
                    <p className="text-center text-sm">
                        Remember your password? <Link to={'/login'} className="hover:underline font-bold">Sign in</Link>
                    </p>
                </div>
            </main>
        </div>
    )
}

export default ForgotPassword
