import React, { useState } from 'react';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '../../firebase/firebase';
import ProductImageUpload from './ProductImageUpload';

export default function ProductEditForm({ product, onClose, onProductUpdated }) {
  const [form, setForm] = useState({ ...product });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setSaving(true);
    setError('');
    try {
      await updateDoc(doc(db, 'products', product.id), form);
      onProductUpdated();
    } catch (err) {
      setError('Gagal mengupdate produk.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-30">
      <div className="bg-white p-6 rounded shadow-lg w-full max-w-md text-gray-900">
        <h2 className="text-xl font-bold mb-4 text-gray-900">Edit Produk</h2>
        <form onSubmit={handleSubmit}>
          <input name="name" value={form.name} onChange={handleChange} className="mb-2 w-full p-2 border rounded text-gray-900 placeholder-gray-500" placeholder="Nama" required />
          <input name="price" value={form.price} onChange={handleChange} className="mb-2 w-full p-2 border rounded text-gray-900 placeholder-gray-500" placeholder="Harga" required />
          <ProductImageUpload
            productId={product.id}
            initialImageUrl={form.imageUrl}
            onUploadSuccess={url => setForm(f => ({ ...f, imageUrl: url }))}
          />
          <select name="type" value={form.type || ''} onChange={handleChange} className="mb-2 w-full p-2 border rounded text-gray-900 placeholder-gray-500" required>
            <option value="">Pilih Tipe Mobil</option>
            <option value="SUV">SUV</option>
            <option value="HATCHBACK">HATCHBACK</option>
            <option value="MPV">MPV</option>
            <option value="SEDAN">SEDAN</option>
          </select>
          <textarea name="desc" value={form.desc} onChange={handleChange} className="mb-2 w-full p-2 border rounded text-gray-900 placeholder-gray-500" placeholder="Deskripsi" required />
          {error && <div className="mb-2 text-red-600">{error}</div>}
          <div className="flex justify-end gap-2">
            <button type="button" className="px-4 py-2 bg-gray-300 rounded" onClick={onClose}>Batal</button>
            <button type="submit" disabled={saving} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
