
import emailjs from '@emailjs/browser';

/**
 * Sends a signup request email to teranoace@gmail.com using EmailJS.
 * @param {string} email - The email address of the requester.
 * @param {string} message - The message provided by the requester.
 * @returns {Promise} - Resolves if the email is sent successfully, rejects otherwise.
 */
export async function sendSignupRequest(email, message) {
    const serviceID = 'service_6p22bud';
    const templateID = 'template_5jwhb4l';
    const userID = '1Wrr3tO9webkKwslK'; // public key

    // These keys MUST match the variables in your EmailJS template
    const templateParams = {
        to_email: 'teranoace@gmail.com', // matches {{to_email}}
        from_email: email,               // matches {{from_email}}
        message: message,                // matches {{message}}
    };
    // Debug: log params to ensure they're not empty
    console.log('[EmailJS] Sending params:', templateParams);
    if (!email || !message) {
        console.error('[EmailJS] ERROR: email or message is empty!', { email, message });
        throw new Error('Email and message are required');
    }
    try {
        const result = await emailjs.send(serviceID, templateID, templateParams, userID);
        console.log('[EmailJS] Success:', result);
        return result;
    } catch (error) {
        console.error('[EmailJS] Error:', error);
        if (error && error.text) {
            alert('EmailJS error: ' + error.text);
        }
        throw error;
    }
}
