import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { db } from '../../firebase/firebase';
import { collection, getDocs } from 'firebase/firestore';
import CustomerInquiry from './inquiry';

const CAR_TYPES = [
  { key: 'ALL', label: 'All' },
  { key: 'SUV', label: 'SUV' },
  { key: 'HATCHBACK', label: 'Hatchback' },
  { key: 'MPV', label: 'MPV' },
  { key: 'SEDAN', label: 'Sedan' },
];

const carouselImages = [
  {
    src: '/LandingPage-Fortuner.jpg',
    alt: 'Toyota Fortuner',
    title: 'Toyota Fortuner',
    subtitle: 'Unmatched Performance & Luxury',
  },
  {
    src: '/LandingPage-Hilux.jpg',
    alt: 'Toyota Hilux',
    title: 'Toyota Hilux',
    subtitle: 'Built for the Toughest Terrains',
  },
  {
    src: '/LangingPage-Landcruiser.jpg',
    alt: 'Toyota Land Cruiser',
    title: 'Toyota Land Cruiser',
    subtitle: 'Legendary Performance & Refinement',
  }
];

const LandingPage = () => {
  const carouselRef = useRef(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isScrolled, setIsScrolled] = useState(false);
  const [products, setProducts] = useState([]);
  const [selectedType, setSelectedType] = useState('ALL');
  const [loading, setLoading] = useState(true);
  const [inquiryOpen, setInquiryOpen] = useState(false);
  const [carInterestPrefill, setCarInterestPrefill] = useState('');
  const [isScrolling, setIsScrolling] = useState(false);

  // Smooth scroll function with animation frame
  const smoothScroll = (element, direction) => {
    if (isScrolling || !element) return;
    
    setIsScrolling(true);
    const start = element.scrollLeft;
    const target = direction === 'left' ? Math.max(0, start - 300) : start + 300;
    const distance = target - start;
    const duration = 500; // Animation duration in ms
    let startTime = null;

    const animateScroll = (currentTime) => {
      if (!startTime) startTime = currentTime;
      const timeElapsed = currentTime - startTime;
      const progress = Math.min(timeElapsed / duration, 1);
      
      // Easing function (easeInOutQuad)
      const easeInOutQuad = t => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
      const scrollProgress = easeInOutQuad(progress);
      
      element.scrollLeft = start + (distance * scrollProgress);
      
      if (timeElapsed < duration) {
        requestAnimationFrame(animateScroll);
      } else {
        setIsScrolling(false);
      }
    };

    requestAnimationFrame(animateScroll);
  };

  // Fetch products from Firestore
  useEffect(() => {
    async function fetchProducts() {
      const querySnapshot = await getDocs(collection(db, 'products'));
      setProducts(querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      setLoading(false);
    }
    fetchProducts();
  }, []);

  const filteredProducts = selectedType === 'ALL'
    ? products
    : products.filter(product => product.type === selectedType);

  const handleCardClick = (product) => {
    setCarInterestPrefill(product.name);
    setInquiryOpen(true);
  };

  // Auto-advance carousel - 7 second interval
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentImageIndex((prevIndex) => 
        prevIndex === carouselImages.length - 1 ? 0 : prevIndex + 1
      );
    }, 7000);
    return () => clearInterval(timer);
  }, []);

  // Handle scroll for navbar
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Handle manual carousel navigation
  const goToSlide = (index) => {
    setCurrentImageIndex(index);
  };

  return (
    <div className="min-h-screen">
      {/* Navigation Bar */}
      <nav 
        className={`fixed w-full z-50 transition-all duration-300 ${
          isScrolled ? 'bg-white shadow-md' : 'bg-transparent'
        }`}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex-shrink-0">
              <img
                className="h-10 w-auto"
                src="/auto2000-logo.png"
                alt="Auto2000"
              />
            </div>
            <div className="hidden md:block">
              <div className="flex items-center space-x-8">
                <a href="#vehicles" className={`text-sm font-medium ${isScrolled ? 'text-gray-800' : 'text-white'} hover:text-red-600 transition-colors`}>
                  Vehicles
                </a>
                <a href="#promotions" className={`text-sm font-medium ${isScrolled ? 'text-gray-800' : 'text-white'} hover:text-red-600 transition-colors`}>
                  Promotions
                </a>
                <a href="#services" className={`text-sm font-medium ${isScrolled ? 'text-gray-800' : 'text-white'} hover:text-red-600 transition-colors`}>
                  Services
                </a>
                <Link 
                  to="/product" 
                  className={`text-sm font-medium ${isScrolled ? 'text-gray-800' : 'text-white'} hover:text-red-600 transition-colors`}
                >
                  Inquiry
                </Link>
              </div>
            </div>
            <div className="hidden md:block">
              <Link
                to="/product"
                className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md text-white bg-red-600 hover:bg-red-700 transition-colors"
              >
                Book a Test Drive
              </Link>
            </div>
          </div>
        </div>
      </nav>

      {/* Full-screen Carousel */}
      <div className="relative h-screen w-full overflow-hidden">
        <AnimatePresence initial={false} mode="wait">
          <motion.div
            key={currentImageIndex}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="absolute inset-0 w-full h-full"
          >
            <img
              src={carouselImages[currentImageIndex].src}
              alt={carouselImages[currentImageIndex].alt}
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent flex items-end pb-32">
              <div className="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-white">
                <div className="max-w-2xl ml-auto text-right">
                  <motion.h1 
                    initial={{ y: 20, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.3, duration: 0.6 }}
                    className="text-3xl md:text-5xl font-normal mb-2 leading-tight"
                    style={{ fontFamily: 'sans-serif' }}
                  >
                    {carouselImages[currentImageIndex].title}
                  </motion.h1>
                  <motion.p 
                    initial={{ y: 20, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.5, duration: 0.6 }}
                    className="text-lg md:text-xl mb-6 font-light"
                  >
                    {carouselImages[currentImageIndex].subtitle}
                  </motion.p>
                  <motion.div
                    initial={{ y: 20, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.7, duration: 0.6 }}
                    className="flex justify-end mt-8"
                  >
                    <Link
                      to="/product"
                      className="inline-flex items-center justify-center px-8 py-3 text-base font-medium text-black bg-white rounded-full hover:bg-gray-100 transition-all duration-300 shadow-md"
                      style={{ minWidth: '180px' }}
                    >
                      Learn More
                    </Link>
                  </motion.div>
                </div>
              </div>
            </div>
          </motion.div>
        </AnimatePresence>

        {/* Carousel Indicators */}
        <div className="absolute bottom-8 left-0 right-0">
          <div className="flex justify-center space-x-2">
            {carouselImages.map((_, index) => (
              <button
                key={index}
                onClick={() => goToSlide(index)}
                className={`w-3 h-3 rounded-full transition-all ${
                  index === currentImageIndex 
                    ? 'bg-white w-8' 
                    : 'bg-white bg-opacity-50 hover:bg-opacity-75'
                }`}
                aria-label={`Go to slide ${index + 1}`}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Vehicle Showcase Section */}
      <div className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-3xl font-bold text-gray-900">Explore Our Range</h2>
            <div className="flex space-x-2">
              <button 
                onClick={() => smoothScroll(carouselRef.current, 'left')}
                className={`w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center hover:bg-gray-50 transition-all duration-300 transform hover:scale-105 ${isScrolling ? 'opacity-50 cursor-not-allowed' : ''}`}
                aria-label="Previous"
                disabled={isScrolling}
              >
                <svg className="w-5 h-5 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
              </button>
              <button 
                onClick={() => smoothScroll(carouselRef.current, 'right')}
                className="w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center hover:bg-gray-50 transition-all duration-300 transform hover:scale-105"
                aria-label="Next"
                disabled={isScrolling}
              >
                <svg className="w-5 h-5 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>
          </div>

          <div className="flex space-x-2 mb-8 overflow-x-auto pb-4 -mx-4 px-4">
            {CAR_TYPES.map((type) => (
              <button
                key={type.key}
                onClick={() => setSelectedType(type.key)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                  selectedType === type.key
                    ? 'bg-red-600 text-white'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                {type.label}
              </button>
            ))}
          </div>

          {loading ? (
            <div className="flex justify-center items-center h-64">
              <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-red-600"></div>
            </div>
          ) : (
            <div className="relative">
              <div 
                ref={carouselRef}
                className={`flex space-x-8 overflow-x-auto pb-8 -mx-4 px-4 scrollbar-hide transition-transform duration-300 ${isScrolling ? 'cursor-wait' : ''}`}
                style={{ 
                  scrollbarWidth: 'none', 
                  msOverflowStyle: 'none',
                  scrollBehavior: 'smooth'
                }}
              >
                {filteredProducts.map((product) => (
                  <div 
                    key={product.id} 
                    className="flex-shrink-0 w-80 bg-white rounded-xl overflow-hidden shadow-md border border-gray-100"
                  >
                    <div className="h-48 bg-gray-100">
                      <img
                        src={product.imageUrl || '/placeholder-car.jpg'}
                        alt={product.name}
                        className="w-full h-full object-cover"
                      />
                    </div>
                    <div className="p-6">
                      <h3 className="text-lg font-bold text-gray-900 mb-1">{product.name}</h3>
                      <p className="text-red-600 font-medium mb-4">
                        {product.price ? `From $${product.price.toLocaleString()}` : 'Price on request'}
                      </p>
                      <div className="h-12 mb-4 overflow-hidden">
                        <p className="text-sm text-gray-600 line-clamp-2">
                          {product.description || 'Experience the perfect blend of performance and style.'}
                        </p>
                      </div>
                      <button
                        onClick={() => handleCardClick(product)}
                        className="w-full py-2.5 bg-red-600 text-white text-sm font-medium rounded-full hover:bg-red-700 transition-colors"
                      >
                        Inquiry
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Inquiry Modal */}
      {inquiryOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4"
          onClick={e => e.target === e.currentTarget && setInquiryOpen(false)}
        >
          <div className="bg-white rounded-lg w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl font-semibold">Inquiry Form</h3>
                <button
                  onClick={() => setInquiryOpen(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              <CustomerInquiry carInterestPrefill={carInterestPrefill} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LandingPage;
