import React from 'react';
import { Routes, Route, Navigate, Outlet } from 'react-router-dom';
import Login from './components/auth/login';
import ForgotPassword from './components/auth/forgot-password';
import CustomerInquiry from './components/customer/inquiry';
import LandingPage from './components/customer/LandingPage';
import ProductListAdmin from './components/admin/ProductListAdmin';
import Signup from './components/auth/Signup';
import ApproveSignup from './components/admin/ApproveSignup';
import AdminProductEdit from './components/admin/AdminProductEdit';
import SalesDashboard from './components/salesman/SalesDashboard';
import SalesGuidesManager from './components/admin/SalesGuidesManager';
import AdminLayout from './components/admin/AdminLayout';
import AdminDashboard from './components/admin/dashboard';
import SalesmanProfile from './components/admin/SalesmanProfile';
import { AuthProvider } from './contexts/authContext/index.jsx';
import ProtectedRoute from './components/ProtectedRoute';

function App() {
  // Layout component for protected routes that need the sales dashboard layout
  const SalesLayout = () => {
    return (
      <ProtectedRoute>
        <SalesDashboard>
          <Outlet />
        </SalesDashboard>
      </ProtectedRoute>
    );
  };

  // Layout component for admin routes
  const AdminRoutes = () => {
    return (
      <ProtectedRoute requiredRole="admin">
        <AdminLayout>
          <Outlet />
        </AdminLayout>
      </ProtectedRoute>
    );
  };

  return (
    <AuthProvider>
      <div className="min-h-screen">
        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={<Login />} />
          <Route path="/forgot-password" element={<ForgotPassword />} />
          <Route path="/signup" element={<Signup />} />
          <Route path="/inquiry" element={<CustomerInquiry />} />
          
          {/* Main landing page with product showcase */}
          <Route path="/" element={<LandingPage />} />
          
          {/* Protected routes with Sales Dashboard layout */}
          <Route element={<SalesLayout />}>
            <Route path="/encrypted-dashboard" element={<AdminDashboard />} />
            <Route path="/encrypted-dashboard/guides" element={<SalesGuidesManager readOnly />} />
            <Route path="/encrypted-dashboard/profile" element={<SalesmanProfile />} />
          </Route>
          
          {/* Admin routes with Admin Layout */}
          <Route element={<AdminRoutes />}>
            <Route path="/admin" element={<Navigate to="/admin/products" replace />} />
            <Route path="/admin/products" element={<ProductListAdmin />} />
            <Route path="/admin/products/edit/:id" element={<AdminProductEdit />} />
            <Route path="/admin/signup-requests" element={<ApproveSignup />} />
            <Route path="/admin/sales-guides" element={<SalesGuidesManager />} />
          </Route>
          
          {/* Catch all other routes */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </AuthProvider>
  )
}

export default App;
